"use client";

import {
  useCallback,
  useEffect,
  useMemo,
  useState,
} from "react";
import {
  useParams,
  useRouter,
} from "next/navigation";

type DoraFirm = {
  id: string;
  firm_name: string;
  employee_count?: number | null;
};

type DoraEmployee = {
  id?: string;
  full_name?: string;
  fullName?: string;
  tc_no?: string;
  tcNo?: string;
  position?: string;
  jobTitle?: string;
  department?: string;
};

type TrainingParticipant = {
  employeeId: string;
  fullName: string;
  tcNo: string;
  jobTitle: string;
  department: string;
};

type TrainingItem = {
  id: string;
  title: string;
  trainingType: string;
  trainingDate: string;
  trainingHours: string;
  startTime: string;
  endTime: string;
  place: string;
  trainerName: string;
  status: string;
  participants: TrainingParticipant[];
};

type CertificateItem = {
  id: string;
  certificateNo: string;
  employeeName: string;
  employeeTc: string;
  employeePosition: string;
  trainingId: string;
  trainingTitle: string;
  trainingType: string;
  trainingDate: string;
  issueDate: string;
  validUntil: string;
  trainerName: string;
  trainingHours: string;
  status: string;
  note: string;
  autoGenerated: boolean;
};

type SyncResponse = {
  success?: boolean;
  error?: string;
  firm?: DoraFirm | null;
  employees?: DoraEmployee[];
  trainings?: { items?: unknown[] };
  certificates?: { items?: unknown[] };
};

function value(v: unknown) {
  return String(v ?? "").trim();
}

function uid(prefix: string) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

function today() {
  return new Date().toLocaleDateString("tr-TR");
}

function emptyTraining(): TrainingItem {
  return {
    id: uid("training"),
    title: "Temel İş Sağlığı ve Güvenliği Eğitimi",
    trainingType: "TEMEL_ISG",
    trainingDate: today(),
    trainingHours: "8",
    startTime: "09:00",
    endTime: "17:00",
    place: "",
    trainerName: "",
    status: "PLANLANDI",
    participants: [],
  };
}

function mapEmployee(row: DoraEmployee): TrainingParticipant {
  return {
    employeeId: value(row.id),
    fullName: value(row.full_name ?? row.fullName),
    tcNo: value(row.tc_no ?? row.tcNo),
    jobTitle: value(row.position ?? row.jobTitle),
    department: value(row.department),
  };
}

function mapTraining(row: any, index: number): TrainingItem {
  return {
    id: value(row?.id) || `training-${index}`,
    title: value(row?.title ?? row?.trainingName) || "İSG Eğitimi",
    trainingType: value(row?.trainingType ?? row?.training_type) || "TEMEL_ISG",
    trainingDate: value(row?.trainingDate ?? row?.training_date),
    trainingHours: value(row?.trainingHours ?? row?.training_hours) || "8",
    startTime: value(row?.startTime ?? row?.trainingStartTime) || "09:00",
    endTime: value(row?.endTime ?? row?.trainingEndTime) || "17:00",
    place: value(row?.place ?? row?.trainingPlace),
    trainerName: value(row?.trainerName ?? row?.trainer_name),
    status: value(row?.status) || "PLANLANDI",
    participants: Array.isArray(row?.participants)
      ? row.participants.map((p: any) => ({
          employeeId: value(p?.employeeId ?? p?.id),
          fullName: value(p?.fullName ?? p?.full_name),
          tcNo: value(p?.tcNo ?? p?.tc_no),
          jobTitle: value(p?.jobTitle ?? p?.position),
          department: value(p?.department),
        }))
      : [],
  };
}

function mapCertificate(row: any, index: number): CertificateItem {
  return {
    id: value(row?.id) || `certificate-${index}`,
    certificateNo: value(row?.certificateNo ?? row?.certificate_no),
    employeeName: value(row?.employeeName ?? row?.employee_name),
    employeeTc: value(row?.employeeTc ?? row?.employee_tc),
    employeePosition: value(row?.employeePosition ?? row?.employee_position),
    trainingId: value(row?.trainingId ?? row?.training_id),
    trainingTitle: value(row?.trainingTitle ?? row?.training_title),
    trainingType: value(row?.trainingType ?? row?.training_type),
    trainingDate: value(row?.trainingDate ?? row?.training_date),
    issueDate: value(row?.issueDate ?? row?.issue_date) || today(),
    validUntil: value(row?.validUntil ?? row?.valid_until),
    trainerName: value(row?.trainerName ?? row?.trainer_name),
    trainingHours: value(row?.trainingHours ?? row?.training_hours),
    status: value(row?.status) || "GECERLI",
    note: value(row?.note),
    autoGenerated: Boolean(row?.autoGenerated ?? row?.auto_generated),
  };
}

async function readJson<T>(response: Response, name: string): Promise<T> {
  const type = response.headers.get("content-type") || "";
  if (!type.toLowerCase().includes("application/json")) {
    const raw = await response.text();
    throw new Error(
      `${name} JSON döndürmedi. HTTP ${response.status}. ${raw
        .replace(/\s+/g, " ")
        .slice(0, 180)}`
    );
  }
  return (await response.json()) as T;
}

export default function DoraTrainingPage() {
  const router = useRouter();
  const params = useParams();
  const firmId = value(params?.firmId);

  const [firm, setFirm] = useState<DoraFirm | null>(null);
  const [employees, setEmployees] = useState<TrainingParticipant[]>([]);
  const [trainings, setTrainings] = useState<TrainingItem[]>([]);
  const [certificates, setCertificates] = useState<CertificateItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [trainingOpen, setTrainingOpen] = useState(false);
  const [trainingForm, setTrainingForm] = useState<TrainingItem>(emptyTraining());
  const [certificateOpen, setCertificateOpen] = useState(false);
  const [certificateForm, setCertificateForm] = useState<CertificateItem | null>(null);
  const [employeeSearch, setEmployeeSearch] = useState("");

  const load = useCallback(async () => {
    if (!firmId) return;
    try {
      setLoading(true);
      setError("");

      const response = await fetch(
        `/api/dora/mobile/sync?firmId=${encodeURIComponent(firmId)}`,
        {
          cache: "no-store",
          headers: {
            "x-api-key": "dsec_mobile_123",
            Accept: "application/json",
          },
        }
      );

      const json = await readJson<SyncResponse>(
        response,
        "DORA Eğitim ve Sertifika senkron servisi"
      );

      if (!response.ok || json.success === false) {
        throw new Error(json.error || "Eğitim ve sertifika verileri alınamadı.");
      }

      setFirm(json.firm ?? null);
      setEmployees(
        (Array.isArray(json.employees) ? json.employees : [])
          .map(mapEmployee)
          .filter((x) => x.fullName)
      );
      setTrainings(
        (Array.isArray(json.trainings?.items) ? json.trainings!.items! : [])
          .map(mapTraining)
      );
      setCertificates(
        (Array.isArray(json.certificates?.items) ? json.certificates!.items! : [])
          .map(mapCertificate)
      );
    } catch (e) {
      setError(e instanceof Error ? e.message : "Merkez yüklenemedi.");
    } finally {
      setLoading(false);
    }
  }, [firmId]);

  useEffect(() => {
    void load();
  }, [load]);

  async function persist(
    nextTrainings: TrainingItem[],
    nextCertificates: CertificateItem[] = certificates,
    message = "Kayıtlar güncellendi."
  ) {
    setSaving(true);
    try {
      const response = await fetch("/api/dora/mobile/sync", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-api-key": "dsec_mobile_123",
          Accept: "application/json",
        },
        body: JSON.stringify({
          firmId,
          trainings: {
            items: nextTrainings,
            count: nextTrainings.length,
            updatedAtMillis: Date.now(),
          },
          certificates: {
            items: nextCertificates,
            count: nextCertificates.length,
            updatedAtMillis: Date.now(),
          },
        }),
      });

      const json = await readJson<SyncResponse>(
        response,
        "DORA Eğitim ve Sertifika kayıt servisi"
      );

      if (!response.ok || json.success === false) {
        throw new Error(json.error || "Kayıt işlemi başarısız.");
      }

      setTrainings(
        (Array.isArray(json.trainings?.items) ? json.trainings!.items! : nextTrainings)
          .map(mapTraining)
      );
      setCertificates(
        (Array.isArray(json.certificates?.items)
          ? json.certificates!.items!
          : nextCertificates
        ).map(mapCertificate)
      );
      setSuccess(message);
    } finally {
      setSaving(false);
    }
  }

  function participantSelected(employee: TrainingParticipant) {
    return trainingForm.participants.some((p) =>
      employee.tcNo
        ? p.tcNo === employee.tcNo
        : p.fullName === employee.fullName
    );
  }

  function toggleParticipant(employee: TrainingParticipant) {
    const selected = participantSelected(employee);

    setTrainingForm((current) => ({
      ...current,
      participants: selected
        ? current.participants.filter((p) =>
            employee.tcNo
              ? p.tcNo !== employee.tcNo
              : p.fullName !== employee.fullName
          )
        : [...current.participants, employee],
    }));
  }

  async function saveTraining() {
    if (!trainingForm.title.trim()) {
      alert("Eğitim adı zorunludur.");
      return;
    }

    if (trainingForm.participants.length === 0) {
      alert("Eğitime en az bir katılımcı seçilmelidir.");
      return;
    }

    const exists = trainings.some((x) => x.id === trainingForm.id);
    const next = exists
      ? trainings.map((x) => (x.id === trainingForm.id ? trainingForm : x))
      : [...trainings, trainingForm];

    try {
      await persist(
        next,
        certificates,
        trainingForm.status === "TAMAMLANDI"
          ? "Eğitim tamamlandı. Katılımcı sertifikaları otomatik oluşturuldu."
          : "Eğitim kaydı başarıyla kaydedildi."
      );
      setTrainingOpen(false);
      setTrainingForm(emptyTraining());
      await load();
    } catch (e) {
      alert(e instanceof Error ? e.message : "Eğitim kaydedilemedi.");
    }
  }

  async function deleteTraining(id: string) {
    if (!confirm("Bu eğitim kaydı silinsin mi?")) return;
    try {
      await persist(
        trainings.filter((x) => x.id !== id),
        certificates.filter((x) => x.trainingId !== id),
        "Eğitim ve bağlı sertifikalar silindi."
      );
      await load();
    } catch (e) {
      alert(e instanceof Error ? e.message : "Eğitim silinemedi.");
    }
  }

  async function saveCertificate() {
    if (!certificateForm) return;
    const next = certificates.map((x) =>
      x.id === certificateForm.id ? certificateForm : x
    );

    try {
      await persist(trainings, next, "Sertifika güncellendi.");
      setCertificateOpen(false);
      setCertificateForm(null);
      await load();
    } catch (e) {
      alert(e instanceof Error ? e.message : "Sertifika güncellenemedi.");
    }
  }

  async function deleteCertificate(id: string) {
    if (!confirm("Bu sertifika kaydı silinsin mi?")) return;
    try {
      await persist(
        trainings,
        certificates.filter((x) => x.id !== id),
        "Sertifika silindi."
      );
      await load();
    } catch (e) {
      alert(e instanceof Error ? e.message : "Sertifika silinemedi.");
    }
  }

  const filteredEmployees = useMemo(() => {
    const q = employeeSearch.trim().toLocaleLowerCase("tr-TR");
    if (!q) return employees;
    return employees.filter((x) =>
      [x.fullName, x.tcNo, x.jobTitle, x.department]
        .join(" ")
        .toLocaleLowerCase("tr-TR")
        .includes(q)
    );
  }, [employees, employeeSearch]);

  const completed = trainings.filter((x) => x.status === "TAMAMLANDI").length;
  const participantTotal = trainings.reduce(
    (sum, x) => sum + x.participants.length,
    0
  );

  if (loading) {
    return <main className="page">DORA Eğitim ve Sertifika Merkezi yükleniyor...</main>;
  }

  return (
    <main className="page">
      <div className="topbar">
        <button
          className="outline"
          onClick={() => router.push(`/admin/dora/${firmId}`)}
        >
          ← Firma Merkezine Dön
        </button>

        <div className="actions">
          <button className="outline" onClick={() => void load()}>
            Web ile Senkronize Et
          </button>
          <button
            className="primary"
            onClick={() => {
              setTrainingForm(emptyTraining());
              setEmployeeSearch("");
              setTrainingOpen(true);
            }}
          >
            + Yeni Eğitim
          </button>
        </div>
      </div>

      <section className="hero">
        <div>
          <div className="eyebrow">DORA • EĞİTİM VE SERTİFİKA</div>
          <h1>Eğitim ve Sertifika Merkezi</h1>
          <p>
            {firm?.firm_name || "DORA firması"} için eğitim oturumları,
            gerçek katılımcılar ve otomatik çalışan sertifikalarını App ↔ Web
            ortak senkron alanında yönetin.
          </p>
        </div>
        <div className="heroNumbers">
          <b>{trainings.length}<small>Eğitim</small></b>
          <b>{certificates.length}<small>Sertifika</small></b>
        </div>
      </section>

      {error ? <div className="error">{error}</div> : null}
      {success ? <div className="success">{success}</div> : null}

      <section className="kpis">
        <Kpi title="Toplam Eğitim" value={trainings.length} detail="Tüm eğitim oturumları" />
        <Kpi title="Tamamlanan" value={completed} detail="Sertifikaya esas eğitim" />
        <Kpi title="Katılım Kaydı" value={participantTotal} detail="Eğitim-katılımcı eşleşmesi" />
        <Kpi title="Sertifika" value={certificates.length} detail="Otomatik + düzenlenen" />
      </section>

      <section className="panel">
        <div className="panelHead">
          <div>
            <span>EĞİTİM OTURUMLARI</span>
            <h2>Katılımcı Bazlı Eğitim Yönetimi</h2>
          </div>
        </div>

        {trainings.length === 0 ? (
          <div className="empty">Henüz eğitim kaydı bulunmuyor.</div>
        ) : (
          <div className="list">
            {trainings.map((training) => (
              <article className="card" key={training.id}>
                <div>
                  <div className="badges">
                    <span className="badge">{training.status}</span>
                    <span className="neutral">{training.participants.length} katılımcı</span>
                  </div>
                  <h3>{training.title}</h3>
                  <p>
                    {training.trainingDate || "Tarih yok"} • {training.trainingHours} saat
                    • {training.startTime}-{training.endTime}
                  </p>
                  <small>
                    {training.trainerName || "Eğitmen belirtilmedi"} •{" "}
                    {training.place || "Yer belirtilmedi"}
                  </small>
                  <div className="participantNames">
                    {training.participants.map((p) => (
                      <span key={`${training.id}-${p.tcNo || p.fullName}`}>
                        {p.fullName}
                      </span>
                    ))}
                  </div>
                </div>
                <div className="actions">
                  <button
                    className="outline"
                    onClick={() => {
                      setTrainingForm({ ...training });
                      setEmployeeSearch("");
                      setTrainingOpen(true);
                    }}
                  >
                    Düzenle / Katılımcılar
                  </button>
                  <button className="danger" onClick={() => void deleteTraining(training.id)}>
                    Sil
                  </button>
                </div>
              </article>
            ))}
          </div>
        )}
      </section>

      <section className="panel">
        <div className="panelHead">
          <div>
            <span>SERTİFİKA MERKEZİ</span>
            <h2>Otomatik Oluşturulan Sertifikalar</h2>
            <p>
              Eğitim durumu “Tamamlandı” olduğunda seçili her katılımcı için tekil
              sertifika otomatik oluşur.
            </p>
          </div>
        </div>

        {certificates.length === 0 ? (
          <div className="empty">Henüz sertifika yok. Tamamlanmış eğitim bekleniyor.</div>
        ) : (
          <div className="certificateGrid">
            {certificates.map((certificate) => (
              <article className="certificateCard" key={certificate.id}>
                <div className="badges">
                  <span className="badge">{certificate.status}</span>
                  {certificate.autoGenerated ? (
                    <span className="auto">DORA Otomatik</span>
                  ) : null}
                </div>
                <h3>{certificate.employeeName}</h3>
                <strong>{certificate.trainingTitle}</strong>
                <p>
                  Belge No: {certificate.certificateNo || "-"}<br />
                  TC: {certificate.employeeTc || "-"}<br />
                  Unvan: {certificate.employeePosition || "-"}<br />
                  Eğitim: {certificate.trainingDate || "-"} • {certificate.trainingHours || "-"} saat<br />
                  Eğitmen: {certificate.trainerName || "-"}<br />
                  Düzenleme: {certificate.issueDate || "-"} • Geçerlilik: {certificate.validUntil || "-"}
                </p>
                <div className="actions">
                  <button
                    className="outline"
                    onClick={() => {
                      setCertificateForm({ ...certificate });
                      setCertificateOpen(true);
                    }}
                  >
                    Düzenle
                  </button>
                  <button
                    className="danger"
                    onClick={() => void deleteCertificate(certificate.id)}
                  >
                    Sil
                  </button>
                </div>
              </article>
            ))}
          </div>
        )}
      </section>

      {trainingOpen ? (
        <div className="backdrop" onMouseDown={() => !saving && setTrainingOpen(false)}>
          <div className="modal" onMouseDown={(e) => e.stopPropagation()}>
            <div className="panelHead">
              <div>
                <span>DORA EĞİTİM FORMU</span>
                <h2>Eğitim + Katılımcılar</h2>
              </div>
              <button className="outline" onClick={() => setTrainingOpen(false)}>×</button>
            </div>

            <div className="formGrid">
              <Field label="Eğitim Adı" value={trainingForm.title}
                onChange={(v) => setTrainingForm({ ...trainingForm, title: v })} />
              <Field label="Eğitim Türü" value={trainingForm.trainingType}
                onChange={(v) => setTrainingForm({ ...trainingForm, trainingType: v })} />
              <Field label="Tarih" value={trainingForm.trainingDate}
                onChange={(v) => setTrainingForm({ ...trainingForm, trainingDate: v })} />
              <Field label="Süre (saat)" value={trainingForm.trainingHours}
                onChange={(v) => setTrainingForm({ ...trainingForm, trainingHours: v })} />
              <Field label="Başlangıç" value={trainingForm.startTime}
                onChange={(v) => setTrainingForm({ ...trainingForm, startTime: v })} />
              <Field label="Bitiş" value={trainingForm.endTime}
                onChange={(v) => setTrainingForm({ ...trainingForm, endTime: v })} />
              <Field label="Yer" value={trainingForm.place}
                onChange={(v) => setTrainingForm({ ...trainingForm, place: v })} />
              <Field label="Eğitmen" value={trainingForm.trainerName}
                onChange={(v) => setTrainingForm({ ...trainingForm, trainerName: v })} />

              <label className="field">
                <span>Durum</span>
                <select
                  value={trainingForm.status}
                  onChange={(e) =>
                    setTrainingForm({ ...trainingForm, status: e.target.value })
                  }
                >
                  <option value="PLANLANDI">Planlandı</option>
                  <option value="DEVAM_EDIYOR">Devam Ediyor</option>
                  <option value="TAMAMLANDI">Tamamlandı</option>
                </select>
              </label>
            </div>

            <div className="participantsBox">
              <div className="participantHeader">
                <div>
                  <h3>Katılımcılar</h3>
                  <p>{trainingForm.participants.length} çalışan seçildi.</p>
                </div>
                <button
                  className="outline"
                  onClick={() =>
                    setTrainingForm({
                      ...trainingForm,
                      participants: employees,
                    })
                  }
                >
                  Tümünü Seç
                </button>
              </div>

              <input
                className="search"
                placeholder="Çalışan adı, TC, unvan veya bölüm ara..."
                value={employeeSearch}
                onChange={(e) => setEmployeeSearch(e.target.value)}
              />

              <div className="employeeList">
                {filteredEmployees.map((employee) => (
                  <label className="employeeRow" key={employee.tcNo || employee.employeeId || employee.fullName}>
                    <input
                      type="checkbox"
                      checked={participantSelected(employee)}
                      onChange={() => toggleParticipant(employee)}
                    />
                    <div>
                      <strong>{employee.fullName}</strong>
                      <small>
                        {employee.tcNo || "TC yok"} • {employee.jobTitle || "Unvan yok"}
                        {employee.department ? ` • ${employee.department}` : ""}
                      </small>
                    </div>
                  </label>
                ))}
              </div>
            </div>

            {trainingForm.status === "TAMAMLANDI" ? (
              <div className="autoInfo">
                Bu eğitim kaydedildiğinde seçili {trainingForm.participants.length} katılımcının
                eksik sertifikaları otomatik oluşturulacaktır.
              </div>
            ) : null}

            <button
              className="primary full"
              disabled={saving}
              onClick={() => void saveTraining()}
            >
              {saving ? "Kaydediliyor..." : "Eğitimi ve Katılımcıları Kaydet"}
            </button>
          </div>
        </div>
      ) : null}

      {certificateOpen && certificateForm ? (
        <div className="backdrop" onMouseDown={() => !saving && setCertificateOpen(false)}>
          <div className="modal certificateModal" onMouseDown={(e) => e.stopPropagation()}>
            <div className="panelHead">
              <div>
                <span>DORA SERTİFİKA</span>
                <h2>{certificateForm.employeeName}</h2>
              </div>
              <button className="outline" onClick={() => setCertificateOpen(false)}>×</button>
            </div>

            <div className="certificateIdentity">
              <b>{certificateForm.certificateNo}</b>
              <span>{certificateForm.trainingTitle}</span>
            </div>

            <div className="formGrid">
              <Field label="Çalışan" value={certificateForm.employeeName}
                onChange={(v) => setCertificateForm({ ...certificateForm, employeeName: v })} />
              <Field label="TC" value={certificateForm.employeeTc}
                onChange={(v) => setCertificateForm({ ...certificateForm, employeeTc: v })} />
              <Field label="Unvan" value={certificateForm.employeePosition}
                onChange={(v) => setCertificateForm({ ...certificateForm, employeePosition: v })} />
              <Field label="Eğitim" value={certificateForm.trainingTitle}
                onChange={(v) => setCertificateForm({ ...certificateForm, trainingTitle: v })} />
              <Field label="Düzenleme Tarihi" value={certificateForm.issueDate}
                onChange={(v) => setCertificateForm({ ...certificateForm, issueDate: v })} />
              <Field label="Geçerlilik Tarihi" value={certificateForm.validUntil}
                onChange={(v) => setCertificateForm({ ...certificateForm, validUntil: v })} />
              <Field label="Eğitmen" value={certificateForm.trainerName}
                onChange={(v) => setCertificateForm({ ...certificateForm, trainerName: v })} />
              <label className="field">
                <span>Durum</span>
                <select
                  value={certificateForm.status}
                  onChange={(e) =>
                    setCertificateForm({ ...certificateForm, status: e.target.value })
                  }
                >
                  <option value="GECERLI">Geçerli</option>
                  <option value="YAKLASIYOR">Süresi Yaklaşıyor</option>
                  <option value="SURESI_DOLDU">Süresi Doldu</option>
                  <option value="IPTAL">İptal</option>
                </select>
              </label>
            </div>

            <label className="field">
              <span>Açıklama</span>
              <textarea
                value={certificateForm.note}
                onChange={(e) =>
                  setCertificateForm({ ...certificateForm, note: e.target.value })
                }
              />
            </label>

            <button className="primary full" disabled={saving} onClick={() => void saveCertificate()}>
              Sertifikayı Güncelle
            </button>
          </div>
        </div>
      ) : null}

      <style jsx>{styles}</style>
    </main>
  );
}

function Kpi({ title, value, detail }: { title: string; value: number; detail: string }) {
  return (
    <article className="kpi">
      <span>{title}</span>
      <strong>{value}</strong>
      <small>{detail}</small>
    </article>
  );
}

function Field({
  label,
  value,
  onChange,
}: {
  label: string;
  value: string;
  onChange: (value: string) => void;
}) {
  return (
    <label className="field">
      <span>{label}</span>
      <input value={value} onChange={(e) => onChange(e.target.value)} />
    </label>
  );
}

